#!/usr/bin/env bash
# Site : une page introuvable (404) qui garde l'habillage du contexte.
# - app/not-found.tsx : adresse inconnue ou page publique introuvable, avec header, ruban et footer du site
#   (rendue à chaque requête : pas de lecture de la base pendant next build) ;
# - (admin)/dashboard/not-found.tsx : dans le panneau de contrôle, retour au tableau de bord ;
# - contenu commun : features/app-shell/PageIntrouvable.tsx. Doc 5.1 à jour, test e2e page-introuvable.
# Pas de migration. Prérequis : apply-docs-routage-conventions.sh.
# Usage (racine du repo) : bash apply-page-introuvable.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/src/app/not-found.tsx" 2>/dev/null | grep -qF "PageIntrouvable"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "### Les fichiers réservés" "apps/web/content/docs/dev/front/routage.mdx" 2>/dev/null || { echo "lancez d'abord apply-docs-routage-conventions.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/dev/front/routage.mdx")
CREATED=("apps/web/src/app/(admin)/dashboard/not-found.tsx" "apps/web/src/app/not-found.tsx" "apps/web/src/features/app-shell/PageIntrouvable.tsx" "e2e/page-introuvable.spec.ts")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "PageIntrouvable" "apps/web/src/app/not-found.tsx" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
if ! git diff --quiet HEAD -- "${MODIFIED[@]}" 2>/dev/null; then echo "❌ modifications non commitées dans des fichiers que ce script modifie (rien n'a été touché) :"; git diff --name-only HEAD -- "${MODIFIED[@]}" | head -5; exit 1; fi
trap 'restore' ERR

